* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #263d3b;
  background: #f4f0e8;
  font-size: 16px;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #fffdf8, #f4f0e8 72%);
}
.card {
  width: min(100%, 460px);
  padding: clamp(22px, 6vw, 38px);
  border: 1px solid #e6dfd2;
  border-radius: 28px;
  background: #fffefa;
  box-shadow: 0 18px 55px #51473516;
}
.intro { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #65827b; font-size: .85rem; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; color: #203a37; font-size: clamp(1.8rem, 7vw, 2.3rem); line-height: 1.12; letter-spacing: -.04em; }
.instructions { max-width: 340px; margin: 14px auto 25px; color: #60716e; line-height: 1.55; }
.game { padding: 18px; border-radius: 22px; background: #f5f3ed; }
.status { min-height: 30px; margin: 0 2px 12px; display: flex; align-items: center; justify-content: space-between; gap: 12px; color: #60716e; }
.status p { margin: 0; }
.status strong { margin-left: 5px; color: #263d3b; font-size: 1.15rem; font-variant-numeric: tabular-nums; }
#result { color: #28766d; font-weight: 800; }
.board {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
  padding: 7px;
  border: 1px solid #e6dfd2;
  border-radius: 16px;
  background: #eae5da;
}
.cell {
  aspect-ratio: 1;
  min-width: 0;
  border: 2px solid #ffffffa8;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 120ms ease, filter 120ms ease, background-color 180ms ease;
}
.cell:hover { z-index: 1; filter: brightness(1.06); transform: scale(1.06); }
.cell:active { transform: scale(.94); }
.cell:focus-visible, button:focus-visible { outline: 3px solid #263d3b; outline-offset: 3px; }
.coral { background-color: #e98772; }
.teal { background-color: #67aaa0; }
.gold { background-color: #edc35f; }
.palette { min-width: 0; margin: 18px 0 15px; padding: 0; border: 0; }
.palette legend { margin-bottom: 10px; color: #526763; font-weight: 700; }
.swatches { display: flex; gap: 11px; }
.swatch {
  width: 48px;
  height: 48px;
  padding: 0;
  border: 3px solid #fffefa;
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 0 0 1px #d9d3c8;
  transition: transform 120ms ease, box-shadow 120ms ease;
}
.swatch:hover { transform: translateY(-2px); }
.swatch[aria-pressed="true"] { box-shadow: 0 0 0 3px #263d3b; }
.swatch:active, .reset:active { transform: scale(.96); }
.reset {
  width: 100%;
  min-height: 48px;
  border: 1px solid #cbd8d3;
  border-radius: 12px;
  background: #e8f0ec;
  color: #2b5952;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: background-color 120ms ease, transform 120ms ease;
}
.reset:hover { background: #dcebe5; }
footer { margin-top: 20px; color: #7b8983; text-align: center; font-size: .9rem; }
@media (max-width: 380px) {
  .game { padding: 14px; }
  .board { gap: 4px; padding: 5px; }
  .cell { border-radius: 6px; }
}

const initialGrid = [
  ['coral', 'coral', 'teal', 'teal', 'gold', 'gold'],
  ['coral', 'teal', 'teal', 'gold', 'gold', 'coral'],
  ['coral', 'coral', 'gold', 'gold', 'teal', 'coral'],
  ['teal', 'coral', 'gold', 'teal', 'teal', 'coral'],
  ['teal', 'teal', 'coral', 'coral', 'gold', 'gold'],
  ['gold', 'teal', 'coral', 'gold', 'gold', 'teal']
];

const board = document.querySelector('#board');
const moveCount = document.querySelector('#move-count');
const result = document.querySelector('#result');
const swatches = [...document.querySelectorAll('.swatch')];
let grid = copyGrid();
let selectedColor = 'coral';
let moves = 0;

function copyGrid() {
  return initialGrid.map(row => [...row]);
}

function render() {
  board.replaceChildren();
  grid.forEach((row, y) => row.forEach((color, x) => {
    const cell = document.createElement('button');
    cell.type = 'button';
    cell.className = `cell ${color}`;
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Row ${y + 1}, column ${x + 1}, ${color}`);
    cell.addEventListener('click', () => fillFrom(y, x));
    board.append(cell);
  }));
}

function fillFrom(y, x) {
  const target = grid[y][x];
  if (target === selectedColor || result.hidden === false) return;

  const region = [];
  const seen = new Set();
  const visit = (row, col) => {
    const key = `${row},${col}`;
    if (row < 0 || row >= 6 || col < 0 || col >= 6 || seen.has(key) || grid[row][col] !== target) return;
    seen.add(key);
    region.push([row, col]);
    visit(row - 1, col);
    visit(row + 1, col);
    visit(row, col - 1);
    visit(row, col + 1);
  };

  visit(y, x);
  region.forEach(([row, col]) => { grid[row][col] = selectedColor; });
  moves += 1;
  moveCount.textContent = moves;
  render();
  if (grid.every(row => row.every(color => color === grid[0][0]))) result.hidden = false;
}

swatches.forEach(button => button.addEventListener('click', () => {
  selectedColor = button.dataset.color;
  swatches.forEach(swatch => swatch.setAttribute('aria-pressed', String(swatch === button)));
}));

document.querySelector('#reset').addEventListener('click', () => {
  grid = copyGrid();
  moves = 0;
  selectedColor = 'coral';
  moveCount.textContent = moves;
  result.hidden = true;
  swatches.forEach(swatch => swatch.setAttribute('aria-pressed', String(swatch.dataset.color === selectedColor)));
  render();
});

render();
